, "any_repository_has_fulltext": true}, "primary_location": {"id": "doi:10.1109/tro.2020.2971415", "doi": "https://doi.org/10.1109/tro.2020.2971415", "is_oa": true, "landing_page_url": "https://doi.org/10.1109/tro.2020.2971415", "pdf_url": "https://ieeexplore.ieee.org/ielx7/8860/9109403/09007490.pdf", "source": {"id": "https://openalex.org/S144620930", "display_name": "IEEE Transactions on Robotics", "issn_l": "1552-3098", "issn": ["1552-3098", "1546-1904", "1941-0468"], "is_oa": false, "is_in_doaj": false, "is_core": true, "listed_in": ["ccf-b", "cwts-core", "dongbi-a", "jufo-3", "norway-2", "poland-200", "russia-white-list-1", "vabb-shw"], "host_organization": "https://openalex.org/P4310319808", "host_organization_name": "Institute of Electrical and Electronics Engineers", "host_organization_lineage": ["https://openalex.org/P4310319808"], "host_organization_lineage_names": ["Institute of Electrical and Electronics Engineers"], "type": "journal"}, "license": null, "license_id": null, "version": "publishedVersion", "is_accepted": true, "is_published": true, "raw_source_name": "IEEE Transactions on Robotics", "raw_type": "journal-article"}, "abstract": "The human input has enabled autonomous systems to improve their capabilities and achieve complex behaviors that are otherwise challenging to generate automatically. Recent work focuses on how robots can use such inputs-such as, demonstrations or corrections-to learn intended objectives. These techniques assume that the human`s desired objective already exists within the robot's hypothesis space. In reality, this assumption is often inaccurate: there will always be situations where the person might care about aspects of the task that the robot does not know about. Without this knowledge, the robot cannot infer the correct objective. Hence, when the robot's hypothesis space is misspecified, even methods that keep track of uncertainty over the objective fail because they reason about which hypothesis might be correct, and not whether any of the hypotheses are correct. In this article, we posit that the robot should reason explicitly about how well it can explain human inputs given its hypothesis space and use that situational confidence to inform how it should incorporate the human input. We demonstrate our method on a 7 degrees-of-freedom robot manipulator in learning from two important types of human inputs: demonstrations of motion planning tasks and physical corrections during the robot's task execution."}]", "excerpt_truncated": true, "source_sha256": "95024b4ff1c247700833951e905447ca1ad9ac9fa8417a1c7701b31e98edc8a0", "verification_required": true, "topic_domain": "creator_objective_critique", "evidence_role": "discovery", "host_tier": "discovery", "source_identity": null, "persistent_identifiers": ["doi:10.52202/079017-1997", "doi:10.1109/tro.2020.2971415", "openalex:W4415797410", "arxiv:2404.08791"], "source_candidates": ["https://doi.org/10.52202/079017-1997", "https://arxiv.org/pdf/2404.08791", "https://doi.org/10.1109/tro.2020.2971415", "https://ieeexplore.ieee.org/ielx7/8860/9109403/09007490.pdf"], "source_candidate_identities": {}}

